397	   * Get a URI to redirect an operation to.
398	   * @param router Router to check.
399	   * @param ugi User group information.
400	   * @param delegation Delegation token.
401	   * @param username User name.
402	   * @param doAsUser Do as user.
403	   * @param path Path to check.
404	   * @param op Operation to perform.
405	   * @param openOffset Offset for opening a file.
406	   * @param excludeDatanodes Blocks to excluded.
407	   * @param parameters Other parameters.
408	   * @return Redirection URI.
409	   * @throws URISyntaxException If it cannot parse the URI.
410	   * @throws IOException If it cannot create the URI.
411	   */
412	  private URI redirectURI(final Router router, final UserGroupInformation ugi,
413	      final DelegationParam delegation, final UserParam username,
414	      final DoAsParam doAsUser, final String path, final HttpOpParam.Op op,
415	      final long openOffset, final String excludeDatanodes,
416	      final Param<?, ?>... parameters) throws URISyntaxException, IOException {
417	    final DatanodeInfo dn =
418	        chooseDatanode(router, path, op, openOffset, excludeDatanodes);
419	
420	    if (dn == null) {
421	      throw new IOException("Failed to find datanode, suggest to check cluster"
422	          + " health. excludeDatanodes=" + excludeDatanodes);
423	    }
424	
425	    final String delegationQuery;
426	    if (!UserGroupInformation.isSecurityEnabled()) {
427	      // security disabled
428	      delegationQuery = Param.toSortedString("&", doAsUser, username);
429	    } else if (delegation.getValue() != null) {
430	      // client has provided a token
431	      delegationQuery = "&" + delegation;
432	    } else {
433	      // generate a token
434	      final Token<? extends TokenIdentifier> t = generateDelegationToken(
435	          ugi, ugi.getUserName());
436	      delegationQuery = "&delegation=" + t.encodeToUrlString();
437	    }
438	
439	    final String redirectQuery = op.toQueryString() + delegationQuery
440	        + "&namenoderpcaddress=" + router.getRouterId()
441	        + Param.toSortedString("&", parameters);
442	    final String uripath = WebHdfsFileSystem.PATH_PREFIX + path;
443	
444	    int port = "http".equals(getScheme()) ? dn.getInfoPort() :
445	        dn.getInfoSecurePort();
446	    final URI uri = new URI(getScheme(), null, dn.getHostName(), port, uripath,
447	        redirectQuery, null);
448	
449	    if (LOG.isTraceEnabled()) {
450	      LOG.trace("redirectURI={}", uri);
451	    }
452	    return uri;
453	  }
