465	    }
466	
467	    if (op == PutOpParam.Op.CREATE) {
468	      try {
469	        resolvedNs = rpcServer.getCreateLocation(path).getNameserviceId();
470	      } catch (IOException e) {
471	        LOG.error("Cannot get the name service " +
472	            "to create file for path {} ", path, e);
473	      }
474	    }
475	
476	    HashSet<Node> excludes = new HashSet<Node>();
477	    Collection<String> collection =
478	        getTrimmedStringCollection(excludeDatanodes);
479	    for (DatanodeInfo dn : dns) {
480	      String ns = getNsFromDataNodeNetworkLocation(dn.getNetworkLocation());
481	      if (collection.contains(dn.getName())) {
482	        excludes.add(dn);
483	      } else if (op == PutOpParam.Op.CREATE && !ns.equals(resolvedNs)) {
484	        // for CREATE, the dest dn should be in the resolved ns
485	        excludes.add(dn);
486	      }
487	    }
488	
489	    if (op == GetOpParam.Op.OPEN ||
490	        op == PostOpParam.Op.APPEND ||
491	        op == GetOpParam.Op.GETFILECHECKSUM) {
492	      // Choose a datanode containing a replica
493	      final ClientProtocol cp = getRpcClientProtocol();
494	      final HdfsFileStatus status = cp.getFileInfo(path);
495	      if (status == null) {
496	        throw new FileNotFoundException("File " + path + " not found.");
497	      }
498	      final long len = status.getLen();
499	      if (op == GetOpParam.Op.OPEN) {
500	        if (openOffset < 0L || (openOffset >= len && len > 0)) {
501	          throw new IOException("Offset=" + openOffset
502	              + " out of the range [0, " + len + "); " + op + ", path=" + path);
503	        }
504	      }
505	
506	      if (len > 0) {
507	        final long offset = op == GetOpParam.Op.OPEN ? openOffset : len - 1;
508	        final LocatedBlocks locations = cp.getBlockLocations(path, offset, 1);
509	        final int count = locations.locatedBlockCount();
510	        if (count > 0) {
511	          LocatedBlock location0 = locations.get(0);
512	          return bestNode(location0.getLocations(), excludes);
513	        }
514	      }
515	    }
516	
517	    return getRandomDatanode(dns, excludes);
518	  }
