520	  /**
521	   * Get the nameservice info from datanode network location.
522	   * @param location network location with format `/ns0/rack1`
523	   * @return nameservice this datanode is in
524	   */
525	  @VisibleForTesting
526	  public static String getNsFromDataNodeNetworkLocation(String location) {
527	    // network location should be in the format of /ns/rack
528	    Pattern pattern = Pattern.compile("^/([^/]*)/");
529	    Matcher matcher = pattern.matcher(location);
530	    if (matcher.find()) {
531	      return matcher.group(1);
532	    }
533	    return "";
534	  }
