536	  /**
537	   * Get a random Datanode from a subcluster.
538	   * @param dns Nodes to be chosen from.
539	   * @param excludes Nodes to be excluded from.
540	   * @return Random datanode from a particular subluster.
541	   */
542	  private static DatanodeInfo getRandomDatanode(
543	      final DatanodeInfo[] dns, final HashSet<Node> excludes) {
544	    DatanodeInfo dn = null;
545	
546	    if (dns == null) {
547	      return dn;
548	    }
549	
550	    int numDNs = dns.length;
551	    int availableNodes = 0;
552	    if (excludes.isEmpty()) {
553	      availableNodes = numDNs;
554	    } else {
555	      for (DatanodeInfo di : dns) {
556	        if (!excludes.contains(di)) {
557	          availableNodes++;
558	        }
559	      }
560	    }
561	
562	    // Return a random one from the list
563	    if (availableNodes > 0) {
564	      while (dn == null || excludes.contains(dn)) {
565	        Random rnd = new Random();
566	        int idx = rnd.nextInt(numDNs);
567	        dn = dns[idx];
568	      }
569	    }
570	    return dn;
571	  }
